fn compute_arith_sum(n: u64) -> u64 {
    // Compute S(n) = 1 + 2 + ... + n
    let mut sum: u64 = 0;
    let mut i: u64 = 1;

    while i <= n {
        sum += i;
        i += 1;
    }

    sum
}

